    for row in grid:
        for val in row:
            count[val] += 1

    # Find special value (appears fewest times but >1)
    sorted_vals = sorted(count.items(), key=lambda x: x[1])
    # Filter out 0 (obstacle marker)
    non_zero = [(k, v) for k, v in sorted_vals if k != 0]
    # Special is the one with fewest occurrences
    non_zero.sort(key=lambda x: x[1])
    special_val = non_zero[0][0] if non_zero else None

    if special_val is None:
        return [row[:] for row in grid]

    # Find start positions (original special value locations)
    start_positions = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == special_val:
                start_positions.append((r, c))

    # BFS to find connected background cells
    # Background = most common value that is not 0 and not special
    bg_count = Counter(val for row in grid for val in row if val != 0 and val != special_val)
    bg_color = bg_count.most_common(1)[0][0] if bg_count else 6

    visited = set()
    for sr, sc in start_positions:
        visited.add((sr, sc))

