            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                # Can traverse through 0s to background cells
                if not visited.add((nr, nc)) and grid[nr][nc] == 0:
                    q.append((nr, nc))

    # Create output grid
    output = [[0] * cols for _ in range(rows)]

    # Fill visited cells (from special value positions through 0s) with special value
    for r, c in visited:
        if grid[r][c] == 0:  # Only replace 0s, keep original special value positions
            output[r][c] = special_val
        else:
            output[r][c] = grid[r][c]

    # Keep 0s that were not reached
    # Keep background unchanged
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0 and (r, c) not in visited:
                output[r][c] = 0
            elif grid[r][c] == bg_color:
                output[r][c] = bg_color
            # Special positions stay as special or connect to 0s

    return output
